UPDATE companies SET description='Valley Fabrication, Inc. was founded in 1973 in La Salle, Illinois. The company operates as a sister concern to Machinery Maintenance, Inc. and On Site Repair Services, Inc., serving Central Illinois from its La Salle base.

The shop provides full-service metal fabrication, including custom weldments, tank and structural steel fabrication, transition and ductwork pieces, stairs, platforms, and conveyor replacement parts. An in-house American Welding Society (AWS) certified training facility runs an apprenticeship program led by a certified instructor.

Valley Fabrication primarily serves industrial maintenance and heavy-equipment sectors in North Central Illinois, repairing buckets, cutting edges, bores, shafts, and wear surfaces for loaders, excavators, dozers, and shovels, as well as screw conveyor flighting, crushers, screeners, and shakers. Its customer base spans cities such as LaSalle, Peru, Ottawa, Spring Valley, Rockford, and Bloomington.

The company emphasizes an AWS-certified workforce, ongoing OSHA safety training, and a mission to deliver the highest value materials and services in the most timely manner. Its apprenticeship program and certified weld inspections are cited as key differentiators.', certifications=ARRAY['AWS Certified Welders','AWS Certified Training Facility','OSHA Certified']::text[], profile='{"capabilities": ["Custom fabrication", "Welding (MIG, TIG, Submerged Arc, Exotic)", "Aluminum welding", "Stainless steel welding", "Monel welding", "Exotic alloy welding", "Steel cutting (up to 6\")", "Plasma cutting (up to 2\")", "Tank fabrication", "Structural steel fabrication", "Transition fabrication (square to round, round to round)", "Ductwork fabrication", "Stairs and platforms fabrication", "Conveyor replacement parts fabrication", "Screw conveyor flighting fabrication", "Repair and rebuilding (buckets, cutting edges, bores, shafts, wear surfaces, loader/excavator/dozer arms, crushers, screeners, shakers, trunnions)", "Build-up and hard surface welding", "AWS certified weld inspections", "AWS certified training facility and apprenticeship program"], "industries": [], "materials": ["Aluminum", "Stainless Steel", "Monel", "Exotic Alloys", "Carbon Steel"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["AWS certified welding training facility and apprenticeship program", "All welders AWS certified", "In-house training facility with certified instructor", "Sister company to Machinery Maintenance and On Site Repair Services"], "facts_used": ["Founded in 1973 -> db, /, /services", "Headquarters in La Salle, Illinois -> db", "Sister company to Machinery Maintenance, Inc. and On Site Repair Services, Inc. -> /, /services", "Over 120,000 square feet of workable space -> /", "40,000+ sq. ft. facility -> /", "Full-service fabrication: custom weldments, tank, structural steel, transitions, ductwork, stairs, platforms, conveyor parts -> /, /services", "Welding processes: MIG, TIG, Submerged Arc, Exotic; materials: Aluminum, Stainless Steel, Monel, Exotics -> /, /services", "Steel cutting up to 6\", plasma cutting up to 2\" -> /", "In-house AWS certified training facility and apprenticeship program -> /services", "All welders AWS certified -> /", "OSHA certified fabricators -> /", "Repair and rebuilding services for heavy equipment (buckets, cutting edges, bores, shafts, wear surfaces, loader/excavator/dozer arms, screw conveyor flighting, crushers, screeners, shakers, trunnions) -> /, /services", "Servicing Central Illinois cities: LaSalle, Peru, Ottawa, Spring Valley, Rockford, Bloomington -> /, /services", "Mission: highest value materials and services in most timely manner -> /services", "Associations: American Welders Association, American Society for Quality, ASME, ASM International, Associated Builders and Contractors -> /services"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "offers a wide variety of metal processing and fabrication services including material production and repairs on a variety of parts and equipment", "founded_year": "1973", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='valley-fabrication-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Valley Steel Services, based in Beverly, West Virginia, has provided steel to Randolph County and surrounding areas since 1980. The operation sits south of Dailey, roughly 11 miles south of Elkins, and serves customers throughout the region.

